# Hindi / Gujarati for Class 10 Science Ch 13 questions.json.
# Templates use {0}, {1}, ... for the formulas (equations) of the English text, in order.
import re
from tr_ch04_common import by_option, feedback, _ITEMS
from common_translations import is_math_only, by_template

_FORMULA = re.compile(r"\$\$[\s\S]+?\$\$|\$[^$]+\$")
P = "sci10ch13.q"
def fill(english, hi, gu):
    f = _FORMULA.findall(english)
    return hi.format(*f), gu.format(*f)
def step_list(iid, manual):
    hi, gu = [], []
    for i, english in enumerate(_ITEMS[iid]["answer_steps"]):
        if i in manual: h, g = fill(english, *manual[i])
        elif is_math_only(english): h = g = english
        elif by_template(english, "hi") is not None: h, g = by_template(english, "hi"), by_template(english, "gu")
        else: raise KeyError(f"{iid}.answer_steps[{i}] needs a translation: {english!r}")
        hi.append(h); gu.append(g)
    return hi, gu
Q = {}
def item(key): return _ITEMS[f"{P}.{key}"]
def add(key, question=None, manual=None, explanation=None, fb=None, options=None):
    iid, it = f"{P}.{key}", item(key)
    if question: Q[f"{iid}.question"] = fill(it["question"], *question)
    if explanation: Q[f"{iid}.explanation"] = fill(it["explanation"], *explanation)
    if "answer_steps" in it: Q[f"{iid}.answer_steps"] = step_list(iid, manual or {})
    if fb is not None:
        english = dict(zip(it["options"], it["option_feedback"]))
        Q[f"{iid}.option_feedback"] = feedback(iid, {o: fill(english[o], *t) for o, t in fb.items()})
    if options: Q[f"{iid}.options"] = by_option(iid, options)
def mc(key, question, explanation, table):
    add(key, question, explanation=explanation, fb={k: v[1] for k, v in table.items()}, options={k: v[0] for k, v in table.items() if not is_math_only(k)} or None)
def tf(key, stmt, expl):
    iid, it = f"{P}.{key}", item(key)
    Q[f"{iid}.question"] = ("बताइए कि निम्नलिखित कथन सत्य है या असत्य: " + stmt[0], "નીચેનું વિધાન સાચું છે કે ખોટું તે જણાવો: " + stmt[1])
    Q[f"{iid}.explanation"] = expl
    Q[f"{iid}.options"] = by_option(iid, {"True": ("सत्य", "સાચું"), "False": ("असत्य", "ખોટું")})
    right = it["options"][it["correct_index"]]
    Q[f"{iid}.option_feedback"] = ([("सही! " if o == right else "पूरी तरह नहीं। ") + expl[0] for o in it["options"]],
                                   [("સાચું! " if o == right else "બરાબર નથી. ") + expl[1] for o in it["options"]])
OK = ("सही!", "સાચું!")

