mc("ex.q3", ("निम्नलिखित में से कौन पर्यावरण-मित्र व्यवहार कहलाते हैं?", "નીચેનામાંથી કયા પર્યાવરણ-મિત્ર વ્યવહાર છે?"),
   ("इनमें से प्रत्येक कचरा कम करता है या ऊर्जा बचाता है।", "આમાંનું દરેક કચરો ઘટાડે છે અથવા ઊર્જા બચાવે છે."),
   {"Carrying cloth-bags to put purchases in while shopping": (("बाज़ार जाते समय सामान के लिए कपड़े का थैला ले जाना", "ખરીદી માટે બજાર જતી વખતે કાપડની થેલી લઈ જવી"), ("सही, पर बाकी भी पर्यावरण-मित्र हैं।", "સાચું, પણ બાકીના પણ પર્યાવરણ-મિત્ર છે.")),
    "Switching off unnecessary lights and fans": (("कार्य समाप्त हो जाने पर लाइट (बल्ब) तथा पंखे का स्विच बंद करना", "કામ ન હોય ત્યારે લાઇટ અને પંખાની સ્વિચ બંધ કરવી"), ("सही, पर बाकी भी पर्यावरण-मित्र हैं।", "સાચું, પણ બાકીના પણ પર્યાવરણ-મિત્ર છે.")),
    "Walking to school instead of getting your mother to drop you on her scooter": (("माँ द्वारा स्कूटर से विद्यालय छोड़ने के बजाय तुम्हारा विद्यालय तक पैदल जाना", "માતા સ્કૂટર પર શાળાએ મૂકવા આવે તેના બદલે ચાલીને શાળાએ જવું"), ("सही, पर बाकी भी पर्यावरण-मित्र हैं।", "સાચું, પણ બાકીના પણ પર્યાવરણ-મિત્ર છે.")),
    "All of the above": (("उपरोक्त सभी", "ઉપરના બધા"), OK)})
add("ex.q4", ("क्या होगा यदि हम एक पोषी स्तर के सभी जीवों को समाप्त कर दें (मार डालें)?", "જો આપણે એક પોષકસ્તરના બધા સજીવોને નાશ કરી દઈએ (મારી નાખીએ) તો શું થશે?"),
    {0: ("अगले पोषी स्तर के जीवों का भोजन छिन जाएगा और वे घटेंगे या मर जाएँगे।", "આગલા પોષકસ્તરના સજીવોનો ખોરાક છીનવાઈ જશે અને તે ઘટશે કે મરી જશે."),
     1: ("नीचे के स्तर के जीव अनियंत्रित रूप से बढ़ जाएँगे। आहार श्रृंखला टूट जाएगी और पारितंत्र का संतुलन बिगड़ जाएगा।", "નીચેના સ્તરના સજીવો અનિયંત્રિત રીતે વધી જશે. આહારશૃંખલા તૂટી જશે અને નિવસનતંત્રનું સંતુલન ખોરવાઈ જશે.")})
add("ex.q5", ("क्या किसी पोषी स्तर के सभी सदस्यों को हटाने का प्रभाव भिन्न-भिन्न पोषी स्तरों के लिए अलग-अलग होगा? क्या किसी पोषी स्तर के जीवों को पारितंत्र को प्रभावित किए बिना हटाना संभव है?", "શું કોઈ પોષકસ્તરના બધા સભ્યોને દૂર કરવાની અસર જુદાં જુદાં પોષકસ્તરો માટે જુદી હશે? શું કોઈ પોષકસ્તરના સજીવોને નિવસનતંત્રને નુકસાન કર્યા વિના દૂર કરી શકાય?"),
    {0: ("हाँ, प्रभाव भिन्न होगा। उत्पादकों को हटाने से अन्य सभी स्तरों का भोजन और ऊर्जा समाप्त हो जाएगी, और पूरा पारितंत्र नष्ट हो जाएगा।", "હા, અસર જુદી હશે. ઉત્પાદકોને દૂર કરવાથી બીજાં બધાં સ્તરોનો ખોરાક અને ઊર્જા ખતમ થઈ જશે, અને આખું નિવસનતંત્ર ભાંગી પડશે."),
     1: ("किसी उपभोक्ता स्तर को हटाने से नीचे का स्तर बढ़ेगा और ऊपर का स्तर भूखा रहेगा; अपघटकों को हटाने से पोषकों का पुनःचक्रण रुकेगा और मृत पदार्थ के ढेर लगेंगे।", "કોઈ ઉપભોગી સ્તરને દૂર કરવાથી નીચેનું સ્તર વધશે અને ઉપરનું સ્તર ભૂખ્યું રહેશે; વિઘટકોને દૂર કરવાથી પોષકોનું પુનઃચક્રણ અટકશે અને મૃત પદાર્થોના ઢગલા થશે."),
     2: ("किसी भी पोषी स्तर को बिना हानि के नहीं हटाया जा सकता, क्योंकि सभी स्तर आपस में जुड़े हैं।", "કોઈ પણ પોષકસ્તરને નુકસાન વિના દૂર કરી શકાય નહિ, કારણ કે બધાં સ્તરો એકબીજાં સાથે જોડાયેલાં છે.")})
add("ex.q6", ("जैविक आवर्धन (जैव आवर्धन) क्या है? क्या पारितंत्र के विभिन्न स्तरों पर जैव आवर्धन का प्रभाव भी भिन्न-भिन्न होगा?", "જૈવિક વિશાલન એટલે શું? શું નિવસનતંત્રનાં જુદાં જુદાં સ્તરે જૈવિક વિશાલનનું પ્રમાણ જુદું હશે?"),
    {0: ("क्रमिक पोषी स्तरों पर अनिम्नीकरणीय हानिकारक रसायनों (जैसे पीड़कनाशी) की सांद्रता में वृद्धि जैव आवर्धन है।", "ક્રમિક પોષકસ્તરોએ અવિઘટનીય હાનિકારક રસાયણો (જેમ કે જંતુનાશકો) ની સાંદ્રતામાં વધારો એ જૈવિક વિશાલન છે."),
     1: ("हाँ: सांद्रता उत्पादक स्तर पर सबसे कम और शीर्ष उपभोक्ता स्तर पर सबसे अधिक होती है।", "હા: સાંદ્રતા ઉત્પાદક સ્તરે સૌથી ઓછી અને સર્વોચ્ચ ઉપભોગી સ્તરે સૌથી વધુ હોય છે.")})
add("ex.q7", ("हमारे द्वारा उत्पादित अजैव निम्नीकरणीय कचरे से कौन-सी समस्याएँ उत्पन्न होती हैं?", "આપણે ઉત્પન્ન કરેલા જૈવ-અવિઘટનીય કચરાથી કઈ સમસ્યાઓ ઊભી થાય છે?"),
    {0: ("वे टूटते नहीं, इसलिए कचरे के ढेर के रूप में जमा होते जाते हैं और भूमि घेरते हैं।", "તે તૂટતા નથી, તેથી કચરાના ઢગલા રૂપે ભેગા થતા જાય છે અને જમીન રોકે છે."),
     1: ("वे मृदा और जल को प्रदूषित करते हैं; प्लास्टिक नालियाँ बंद करता है और उसे निगलने वाले जंतुओं को हानि पहुँचाता है।", "તે જમીન અને પાણીને પ્રદૂષિત કરે છે; પ્લાસ્ટિક ગટરો બંધ કરે છે અને તેને ગળી જનાર પ્રાણીઓને નુકસાન કરે છે."),
     2: ("उनके विषैले रसायन आहार श्रृंखलाओं में प्रवेश करके जैव आवर्धन करते हैं, जिससे मनुष्यों को हानि होती है।", "તેમનાં ઝેરી રસાયણો આહારશૃંખલામાં પ્રવેશીને જૈવિક વિશાલન કરે છે, જેથી માણસોને નુકસાન થાય છે.")})
add("ex.q8", ("यदि हमारे द्वारा उत्पादित सारा कचरा जैव निम्नीकरणीय हो, तो क्या इसका हमारे पर्यावरण पर कोई प्रभाव नहीं पड़ेगा?", "જો આપણે ઉત્પન્ન કરેલો બધો કચરો જૈવ-વિઘટનીય હોય, તો શું તેની આપણા પર્યાવરણ પર કોઈ અસર નહિ થાય?"),
    {0: ("फिर भी प्रभाव पड़ेगा: अधिक मात्रा में जैव निम्नीकरणीय कचरा सड़ता है, दुर्गंध देता है और रोग फैलाता है।", "તો પણ અસર થશે: વધુ પ્રમાણમાં જૈવ-વિઘટનીય કચરો સડે છે, દુર્ગંધ આપે છે અને રોગ ફેલાવે છે."),
     1: ("अपघटन से मेथेन जैसी गैसें भी निकलती हैं; कचरे का प्रबंधन आवश्यक है, जैसे कंपोस्ट बनाकर।", "વિઘટનથી મિથેન જેવા વાયુઓ પણ છૂટે છે; કચરાનું વ્યવસ્થાપન જરૂરી છે, જેમ કે ખાતર બનાવીને.")})

