add("vsa1", ("आहार जाल क्या है? यह आहार श्रृंखला से कैसे भिन्न है?", "આહારજાળ એટલે શું? તે આહારશૃંખલાથી કેવી રીતે જુદી છે?"),
    {0: ("आहार श्रृंखला जीवों की एक अकेली श्रृंखला है, जिसमें प्रत्येक अपने से पहले वाले को खाता है।", "આહારશૃંખલા સજીવોની એક જ શ્રેણી છે, જેમાં દરેક પોતાની પહેલાંનાને ખાય છે."),
     1: ("आहार जाल अनेक परस्पर जुड़ी आहार श्रृंखलाओं का जाल है, क्योंकि एक जीव को कई दूसरे जीव खाते हैं।", "આહારજાળ ઘણી એકબીજી સાથે જોડાયેલી આહારશૃંખલાઓની જાળ છે, કારણ કે એક સજીવને ઘણા બીજા સજીવો ખાય છે.")})
add("vsa2", ("हमें CFC-मुक्त रेफ्रिजरेटर क्यों प्रयोग करने चाहिए?", "આપણે CFC-મુક્ત રેફ્રિજરેટર કેમ વાપરવાં જોઈએ?"),
    {0: ("पुराने रेफ्रिजरेटरों और एयर कंडीशनरों से निकलने वाले CFC ओज़ोन परत का अवक्षय करते हैं।", "જૂનાં રેફ્રિજરેટર અને ઍર કન્ડિશનરમાંથી નીકળતાં CFC ઓઝોન સ્તરનો ક્ષય કરે છે."),
     1: ("अवक्षयित ओज़ोन परत अधिक हानिकारक UV विकिरण को पृथ्वी तक आने देती है, जिससे त्वचा का कैंसर होता है और सजीवों को हानि होती है।", "ક્ષય પામેલું ઓઝોન સ્તર વધુ હાનિકારક UV કિરણોને પૃથ્વી સુધી આવવા દે છે, જેથી ચામડીનું કૅન્સર થાય છે અને સજીવોને નુકસાન થાય છે.")})
add("sa1", ("10 प्रतिशत नियम बताइए। यदि कोई पौधा 20 000 J ऊर्जा ग्रहण करता है, तो तृतीयक उपभोक्ता तक कितनी ऊर्जा पहुँचेगी? ऊर्जा के प्रवाह को एकदिशिक क्यों कहते हैं?", "10 % નો નિયમ જણાવો. જો કોઈ વનસ્પતિ 20 000 J ઊર્જા ઝીલે, તો તૃતીય ઉપભોગી સુધી કેટલી ઊર્જા પહોંચશે? ઊર્જાના પ્રવાહને એકમાર્ગી કેમ કહે છે?"),
    {0: ("10% नियम: एक पोषी स्तर की ऊर्जा का केवल लगभग 10% अगले स्तर तक जाता है।", "10 % નો નિયમ: એક પોષકસ્તરની ઊર્જાનો ફક્ત આશરે 10% આગલા સ્તરે જાય છે."),
     1: ("20 000 → 2000 (प्राथमिक) → 200 (द्वितीयक) → 20 J (तृतीयक)।", "20 000 → 2000 (પ્રાથમિક) → 200 (દ્વિતીય) → 20 J (તૃતીય)."),
     2: ("उत्पादकों द्वारा ग्रहण की गई ऊर्जा सूर्य को वापस नहीं जाती, और उपभोक्ताओं को मिली ऊर्जा निचले स्तरों को नहीं लौटती।", "ઉત્પાદકોએ ઝીલેલી ઊર્જા સૂર્યને પાછી જતી નથી, અને ઉપભોગીઓને મળેલી ઊર્જા નીચલાં સ્તરોને પાછી મળતી નથી.")})
add("sa2", ("जैव निम्नीकरणीय और अजैव निम्नीकरणीय पदार्थों में दो-दो उदाहरणों सहित अंतर बताइए। कुछ पदार्थ जैव निम्नीकरणीय क्यों नहीं होते?", "જૈવ-વિઘટનીય અને જૈવ-અવિઘટનીય પદાર્થો વચ્ચે બે-બે ઉદાહરણ સાથે તફાવત આપો. કેટલાક પદાર્થો જૈવ-વિઘટનીય કેમ નથી હોતા?"),
    {0: ("जैव निम्नीकरणीय: अपघटकों द्वारा तोड़े जाते हैं, जैसे सब्ज़ियों के छिलके, कागज़।", "જૈવ-વિઘટનીય: વિઘટકો દ્વારા તૂટે છે, જેમ કે શાકભાજીની છાલ, કાગળ."),
     1: ("अजैव निम्नीकरणीय: जैविक प्रक्रमों द्वारा नहीं तोड़े जाते, जैसे प्लास्टिक, काँच।", "જૈવ-અવિઘટનીય: જૈવિક ક્રિયાઓ દ્વારા તૂટતા નથી, જેમ કે પ્લાસ્ટિક, કાચ."),
     2: ("सूक्ष्मजीवों के एंज़ाइम विशिष्ट होते हैं, इसलिए वे अनेक संश्लेषित पदार्थों पर कार्य नहीं कर सकते।", "સૂક્ષ્મજીવોના ઉત્સેચકો વિશિષ્ટ હોય છે, તેથી તે ઘણા સંશ્લેષિત પદાર્થો પર કાર્ય કરી શકતા નથી.")})
add("la1", ("ओज़ोन परत क्या है? ओज़ोन कैसे बनती है? इसका अवक्षय कैसे हो रहा है, और इसकी रक्षा के लिए क्या कदम उठाए गए हैं?", "ઓઝોન સ્તર શું છે? ઓઝોન કેવી રીતે બને છે? તેનો ક્ષય કેવી રીતે થઈ રહ્યો છે, અને તેના રક્ષણ માટે કયાં પગલાં લેવાયાં છે?"),
    {0: ("ओज़ोन परत वायुमंडल में ऊपर ओज़ोन (O₃) की परत है, जो पृथ्वी को हानिकारक UV विकिरण से बचाती है।", "ઓઝોન સ્તર વાતાવરણમાં ઊંચે ઓઝોન (O₃) નું સ્તર છે, જે પૃથ્વીને હાનિકારક UV કિરણોથી બચાવે છે."),
     1: ("UV विकिरण ऑक्सीजन अणुओं को तोड़ता है: {0}", "UV કિરણો ઑક્સિજન અણુઓને તોડે છે: {0}"),
     2: ("ऑक्सीजन परमाणु ऑक्सीजन अणुओं से मिलते हैं: {0}", "ઑક્સિજન પરમાણુઓ ઑક્સિજન અણુઓ સાથે જોડાય છે: {0}"),
     3: ("प्रशीतकों और अग्निशामकों में प्रयुक्त CFC जैसे संश्लेषित रसायन ओज़ोन परत का अवक्षय करते हैं।", "રેફ્રિજરન્ટ અને અગ્નિશામકોમાં વપરાતાં CFC જેવાં સંશ્લેષિત રસાયણો ઓઝોન સ્તરનો ક્ષય કરે છે."),
     4: ("1987 में UNEP ने CFC उत्पादन को 1986 के स्तर पर सीमित करने का समझौता कराया; अब CFC-मुक्त रेफ्रिजरेटर अनिवार्य हैं।", "1987 માં UNEP એ CFC ઉત્પાદનને 1986 ના સ્તરે સ્થિર કરવાનો કરાર કરાવ્યો; હવે CFC-મુક્ત રેફ્રિજરેટર ફરજિયાત છે.")})
add("la2", ("एक आहार श्रृंखला की सहायता से समझाइए कि पारितंत्र में ऊर्जा का प्रवाह कैसे होता है और पीड़कनाशी कैसे सांद्रित होते हैं। मनुष्यों को सबसे अधिक चिंतित क्यों होना चाहिए?", "એક આહારશૃંખલાની મદદથી સમજાવો કે નિવસનતંત્રમાં ઊર્જાનો પ્રવાહ કેવી રીતે થાય છે અને જંતુનાશકો કેવી રીતે સાંદ્ર બને છે. માણસોએ સૌથી વધુ ચિંતા કેમ કરવી જોઈએ?"),
    {0: ("आहार श्रृंखला: घास → टिड्डा → मेंढक → साँप → बाज़।", "આહારશૃંખલા: ઘાસ → તીતીઘોડો → દેડકો → સાપ → ગરુડ."),
     1: ("उत्पादक सूर्य के प्रकाश का लगभग 1% ग्रहण करते हैं; हर चरण पर ऊर्जा का केवल लगभग 10% आगे जाता है, शेष उपयोग होकर ऊष्मा के रूप में खो जाता है।", "ઉત્પાદકો સૂર્યપ્રકાશનો આશરે 1% ઝીલે છે; દરેક પગથિયે ઊર્જાનો ફક્ત આશરે 10% આગળ જાય છે, બાકીનો વપરાઈને ઉષ્મા સ્વરૂપે ગુમાવાય છે."),
     2: ("इसलिए श्रृंखला में ऊपर जाने पर ऊर्जा तेज़ी से घटती है, और श्रृंखलाएँ छोटी होती हैं।", "તેથી શૃંખલામાં ઉપર જતાં ઊર્જા ઝડપથી ઘટે છે, અને શૃંખલાઓ ટૂંકી હોય છે."),
     3: ("अनिम्नीकरणीय पीड़कनाशी टूटते नहीं, इसलिए उनकी सांद्रता हर स्तर पर बढ़ती है (जैव आवर्धन)।", "અવિઘટનીય જંતુનાશકો તૂટતા નથી, તેથી તેમની સાંદ્રતા દરેક સ્તરે વધે છે (જૈવિક વિશાલન)."),
     4: ("मनुष्य अनेक आहार श्रृंखलाओं के शीर्ष पर है, इसलिए सबसे अधिक सांद्रता हमारे शरीर में इकट्ठी होती है।", "માણસ ઘણી આહારશૃંખલાની ટોચે છે, તેથી સૌથી વધુ સાંદ્રતા આપણા શરીરમાં ભેગી થાય છે.")})
add("cb1", ("एक झील के पास के किसानों ने अपनी फ़सलों पर एक पीड़कनाशी छिड़का। कुछ वर्षों बाद वैज्ञानिकों को इसके अंश झील के जल में, उससे कहीं अधिक मछलियों में, और सबसे अधिक मछली खाने वाले पक्षियों में मिले, जिनके अंडों के कवच पतले हो गए थे।\n\n(i) इस स्थिति में दिखाए गए प्रक्रम का नाम लिखिए। (1)\n\n(ii) किस जीव में पीड़कनाशी की सांद्रता सबसे अधिक थी? (1)\n\n(iii) आहार श्रृंखला में आगे सांद्रता क्यों बढ़ी? अथवा पीड़कनाशियों का सेवन घटाने के दो तरीके सुझाइए। (2)",
             "એક સરોવર પાસેના ખેડૂતોએ પોતાના પાક પર એક જંતુનાશક છાંટ્યું. થોડાં વર્ષો પછી વૈજ્ઞાનિકોને તેના અંશ સરોવરના પાણીમાં, તેનાથી ઘણા વધુ માછલીઓમાં, અને સૌથી વધુ માછલી ખાનારાં પક્ષીઓમાં મળ્યા, જેમનાં ઈંડાંનાં કવચ પાતળાં થઈ ગયાં હતાં.\n\n(i) આ કિસ્સામાં દર્શાવેલી ક્રિયાનું નામ આપો. (1)\n\n(ii) કયા સજીવમાં જંતુનાશકની સાંદ્રતા સૌથી વધુ હતી? (1)\n\n(iii) આહારશૃંખલામાં આગળ સાંદ્રતા કેમ વધી? અથવા જંતુનાશકોનું સેવન ઘટાડવાની બે રીતો સૂચવો. (2)"),
    {0: ("(i) जैव आवर्धन।", "(i) જૈવિક વિશાલન."), 1: ("(ii) मछली खाने वाले पक्षी।", "(ii) માછલી ખાનારાં પક્ષીઓ."),
     2: ("(iii) पीड़कनाशी शरीर में टूटता नहीं; प्रत्येक जीव नीचे के स्तर के अनेक जीव खाता है, इसलिए रसायन इकट्ठा होता है और हर चरण पर उसकी सांद्रता बढ़ती है। अथवा फल और सब्ज़ियाँ उपयोग से पहले अच्छी तरह धोइए; जैविक रूप से उगाया भोजन चुनिए और पीड़कनाशियों के कम उपयोग का समर्थन कीजिए।",
         "(iii) જંતુનાશક શરીરમાં તૂટતું નથી; દરેક સજીવ નીચેના સ્તરના ઘણા સજીવો ખાય છે, તેથી રસાયણ ભેગું થાય છે અને દરેક પગથિયે તેની સાંદ્રતા વધે છે. અથવા ફળો અને શાકભાજી વાપરતાં પહેલાં બરાબર ધુઓ; સેન્દ્રિય રીતે ઉગાડેલો ખોરાક પસંદ કરો અને જંતુનાશકોના ઓછા ઉપયોગને ટેકો આપો.")})
add("cb2", ("एक विद्यालय ने अपना कचरा हरे डिब्बों (गीला कचरा) और नीले डिब्बों (सूखा कचरा) में अलग करना शुरू किया। हरे डिब्बे के कचरे से विद्यालय के बगीचे के लिए कंपोस्ट बनाई गई, और सूखा कचरा पुनःचक्रण के लिए भेजा गया।\n\n(i) हरे डिब्बे में जाने वाले कचरे के दो उदाहरण दीजिए। (1)\n\n(ii) क्या प्लास्टिक जैव निम्नीकरणीय है? (1)\n\n(iii) कंपोस्ट बनाना पर्यावरण की कैसे सहायता करता है? अथवा प्लास्टिक जैसे सूखे कचरे को जलाने या फेंकने से होने वाली दो समस्याएँ बताइए। (2)",
             "એક શાળાએ પોતાનો કચરો લીલા ડબ્બા (ભીનો કચરો) અને વાદળી ડબ્બા (સૂકો કચરો) માં અલગ કરવાનું શરૂ કર્યું. લીલા ડબ્બાના કચરામાંથી શાળાના બગીચા માટે ખાતર બનાવાયું, અને સૂકો કચરો પુનઃચક્રણ માટે મોકલાયો.\n\n(i) લીલા ડબ્બામાં જવો જોઈએ તેવા કચરાનાં બે ઉદાહરણ આપો. (1)\n\n(ii) શું પ્લાસ્ટિક જૈવ-વિઘટનીય છે? (1)\n\n(iii) ખાતર બનાવવું પર્યાવરણને કેવી રીતે મદદ કરે છે? અથવા પ્લાસ્ટિક જેવા સૂકા કચરાને બાળવાથી કે ફેંકવાથી થતી બે સમસ્યાઓ જણાવો. (2)"),
    {0: ("(i) सब्ज़ियों और फलों के छिलके, बचा हुआ भोजन (कोई दो जैव निम्नीकरणीय वस्तुएँ)।", "(i) શાકભાજી અને ફળોની છાલ, વધેલો ખોરાક (કોઈ પણ બે જૈવ-વિઘટનીય વસ્તુઓ)."),
     1: ("(ii) नहीं, प्लास्टिक अजैव निम्नीकरणीय है।", "(ii) ના, પ્લાસ્ટિક જૈવ-અવિઘટનીય છે."),
     2: ("(iii) कंपोस्ट बनाना जैव निम्नीकरणीय कचरे को खाद में बदलता है जो मृदा को समृद्ध करती है, और कचरा भराव स्थलों में जाने वाले कचरे को घटाता है। अथवा प्लास्टिक जलाने से हानिकारक गैसें निकलती हैं जो वायु को प्रदूषित करती हैं; फेंका गया प्लास्टिक मृदा और जल को प्रदूषित करता है और जंतुओं को हानि पहुँचाता है।",
         "(iii) ખાતર બનાવવું જૈવ-વિઘટનીય કચરાને ખાતરમાં ફેરવે છે જે જમીનને સમૃદ્ધ કરે છે, અને લૅન્ડફિલમાં જતો કચરો ઘટાડે છે. અથવા પ્લાસ્ટિક બાળવાથી હાનિકારક વાયુઓ છૂટે છે જે હવાને પ્રદૂષિત કરે છે; ફેંકેલું પ્લાસ્ટિક જમીન અને પાણીને પ્રદૂષિત કરે છે અને પ્રાણીઓને નુકસાન કરે છે.")})
# Assertion-reason
_CORRECT = re.compile(r"^Correct! A is (?:true|false): (.*) R is (?:true|false): (.*)$")
def ar(key, a, r, wa, wr, ex):
    it = item(key)
    a_en, r_en = it["question"].replace("**Assertion (A):** ", "").split("\n\n**Reason (R):** ")
    wa_en, wr_en = _CORRECT.match(it["option_feedback"][it["correct_index"]]).groups()
    (a_hi, a_gu), (r_hi, r_gu) = fill(a_en, *a), fill(r_en, *r)
    (wa_hi, wa_gu), (wr_hi, wr_gu), (ex_hi, ex_gu) = fill(wa_en, *wa), fill(wr_en, *wr), fill(it["explanation"], *ex)
    return (a_hi, r_hi, a_gu, r_gu, wa_hi, wr_hi, wa_gu, wr_gu, ex_hi, ex_gu)
